{"content": "Add-Type -AssemblyName System.Drawing
$path = "uploads\2026-08-20T230724-jimeng-2026-08-18-8526-AWP-SNIPER-RIFLE-WEAPON-DESIGN-SHE.png"
$img = [System.Drawing.Bitmap]::FromFile($path)
$w = $img.Width; $h = $img.Height

# 32 列 × 36 行网格：白底 → 武器剪影
$cols = 32; $rows = 36
$grid = @{}
for ($cy = 0; $cy -lt $rows; $cy++) {
  for ($cx = 0; $cx -lt $cols; $cx++) {
    $x = [int](($cx + 0.5) * $w / $cols); $y = [int](($cy + 0.5) * $h / $rows)
    $p = $img.GetPixel($x, $y)
    $isBg = ($p.R -gt 232 -and $p.G -gt 232 -and $p.B -gt 232)
    $grid["$cx,$cy"] = (-not $isBg)
  }
}

# 逐列：武器的纵向范围 + 主色
Write-Output "--- silhouette profile (col: topRow-bottomRow, dominant color) ---"
for ($cx = 0; $cx -lt $cols; $cx++) {
  $minY = -1; $maxY = -1
  $colorCount = @{}
  for ($cy = 0; $cy -lt $rows; $cy++) {
    if ($grid["$cx,$cy"]) {
      if ($minY -lt 0) { $minY = $cy }
      $maxY = $cy
      # 收集该格主色（16 级量化）
      $x = [int](($cx + 0.5) * $w / $cols); $y = [int](($cy + 0.5) * $h / $rows)
      $p = $img.GetPixel($x, $y)
      $key = "$([int]($p.R/24)),$([int]($p.G/24)),$([int]($p.B/24))"
      if ($colorCount.ContainsKey($key)) { $colorCount[$key]++ } else { $colorCount[$key] = 1 }
    }
  }
  if ($minY -ge 0) {
    # 主色
    $top = $colorCount.GetEnumerator() | Sort-Object Value -Descending | Select-Object -First 1
    $pp = $top.Key -split ','; $r = [int]$pp[0]*24; $g = [int]$pp[1]*24; $b = [int]$pp[2]*24
    $hex = "#{0:X2}{1:X2}{2:X2}" -f $r, $g, $b
    $pctTop = [int]($minY * 100 / $rows); $pctBot = [int]($maxY * 100 / $rows)
    Write-Output ("col{0:D2} top={1}% bot={2}% h={3}%  {4}" -f $cx, $pctTop, $pctBot, [int](($maxY-$minY+1)*100/$rows), $hex)
  } else {
    Write-Output ("col{0:D2} -" -f $cx)
  }
}
$img.Dispose()
